//! ↩️ move-material leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfMaterial;
use crate::artifacts::gltf::schema::mutations::move_material::mutation::{validate, GltfMoveMaterialPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{materials_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-material.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveMaterialInverseOperation { Insert { position: usize, item: GltfMaterial }, Delete { index: usize, removed: GltfMaterial }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveMaterialInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveMaterialPayload, pub operation: GltfMoveMaterialInverseOperation }
fn operation(payload: &GltfMoveMaterialPayload, base: &GltfSnapshot) -> GltfMoveMaterialInverseOperation { GltfMoveMaterialInverseOperation::Move { index: payload.position, position: payload.index } }
fn touched_paths(payload: &GltfMoveMaterialPayload) -> Vec<String> { vec![format!("document/materials/{}", payload.index), format!("document/materials/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfMoveMaterialInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfMoveMaterialInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveMaterialInverseOperation::Insert { position, .. } if *position > after.document.materials.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/materials", "position must be within the collection")), GltfMoveMaterialInverseOperation::Delete { index, .. } if *index >= after.document.materials.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/materials", "index must address an item")), GltfMoveMaterialInverseOperation::Move { index, position } if *index >= after.document.materials.len() || *position >= after.document.materials.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/materials", "indices must address items")), GltfMoveMaterialInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.materials.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.materials.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/materials", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveMaterialInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Materials, &Change::Insert(*position))?; next.document.materials.insert(*position, item.clone());  }, GltfMoveMaterialInverseOperation::Delete { index, .. } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, None, None)?;  }, GltfMoveMaterialInverseOperation::Move { index, position } => { materials_op(&mut next, GltfTopLevelFamily::Materials, *index, Some(*position), None)?;  }, GltfMoveMaterialInverseOperation::Reorder { order } => { materials_op(&mut next, GltfTopLevelFamily::Materials, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfMoveMaterialInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfMoveMaterialPayload, base: &GltfSnapshot) -> Result<GltfMoveMaterialInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveMaterialInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
